head.script:
scwin.autoComplete1_ontoggleclick = function() {
    dataList1.sort("col1", 1);
    console.log("ontoggleclick");
    log = true;
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 개발자모드(F12) console창에서 샘플파일 실행 후 autoComplate에 세모버튼(▼) 클릭한다. 
    //1. In the developer mode (F12) console window, click the sample button and click on the autoComplate button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. console창에 'ontoggleclick' 보여진다. (이전에는 ononclick 이벤트로 세모버튼까지 처리되었음)
    //1. 'ontoggleclick' is displayed in the console window. (Previously the ononclick event handled even the triple button)
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //        dataList1.sort("col1", 1);
    window.log = false;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
